using System;using System.Linq;using System.Reflection;using System.Threading.Tasks;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Object=UnityEngine.Object;using Codely.Newtonsoft.Json;using Polarity.Config;using Polarity.Controllers;using Polarity.Entities;using Polarity.Simulation;using Polarity.Views;using Polarity.Debugging;using Polarity.Model;
var flags=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;EditorApplication.isPaused=true;
async Task<SimulationWorld> Load(){var old=Object.FindObjectOfType<SimulationWorld>();var done=new TaskCompletionSource<SimulationWorld>();UnityEngine.Events.UnityAction<Scene,LoadSceneMode> callback=null;callback=(s,m)=>{SceneManager.sceneLoaded-=callback;EditorApplication.isPaused=true;done.SetResult(Object.FindObjectOfType<SimulationWorld>());};SceneManager.sceneLoaded+=callback;EditorApplication.isPaused=false;if(!old.Level.RequestRestart())throw new Exception("restart rejected");return await done.Task;}
var stepMethod=typeof(SimulationWorld).GetMethod("FixedUpdate",flags);void Step(SimulationWorld w)=>stepMethod.Invoke(w,null);
void Walk(SimulationWorld w,Vector2? target){var delta=target.HasValue?target.Value-w.Player.Rigidbody.position:Vector2.zero;w.Player.SampleMoveInput(delta.y>.15f,delta.x<-.15f,delta.y<-.15f,delta.x>.15f);}
float[] V(Vector2 v)=>new[]{v.x,v.y};
async Task<string> Run(){var runs=new List<object>();foreach(float flip in new[]{.5f,1f,1.5f,2f,3f})foreach(var target in new[]{new Vector2(3,2),new Vector2(3,-2),new Vector2(0,-3),new Vector2(-7,0)}){var w=await Load();var enemy=w.Bodies[0];var crate=w.Bodies[1];var damage=new List<object>();var marks=new List<object>();var traces=new List<object>();w.DamageCommitted+=d=>damage.Add(new{step=d.Step,time=w.SimulationTime,source=d.SourceId,target=d.TargetId,kind=d.Kind.ToString(),hp=d.RemainingHealth,pos=V(d.Position)});w.MarkResolved+=m=>marks.Add(new{step=w.CompletedStepCount,time=w.SimulationTime,id=m.Request.TargetId,polarity=m.Request.Polarity.ToString(),outcome=m.Outcome.ToString()});w.SubmitMark(enemy.BodyId,Polarity.Model.Polarity.Positive);w.SubmitMark(crate.BodyId,Polarity.Model.Polarity.Negative);for(int j=0;j<1500&&w.State.Phase==LevelPhase.Running;j++){if(j==(int)(flip/.02f))w.SubmitMark(crate.BodyId,Polarity.Model.Polarity.Positive);Walk(w,j>=flip/.02f?target:new Vector2(3,2));Step(w);if(j%50==0)traces.Add(new{t=w.SimulationTime,p=V(w.Player.Rigidbody.position),e=V(enemy.Rigidbody.position),c=V(crate.Rigidbody.position)});}runs.Add(new{flip,target=V(target),phase=w.State.Phase.ToString(),time=w.SimulationTime,hp=w.PlayerHealth.CurrentHealth,marks=w.State.RemainingMarks,damage,operations=marks,trace=traces});}System.IO.File.WriteAllText("D:/Code/Polarity/docs/verification/步骤13-种子探索.json",JsonConvert.SerializeObject(runs));return JsonConvert.SerializeObject(runs.Select(r=>new{flip=r.GetType().GetProperty("flip").GetValue(r),target=r.GetType().GetProperty("target").GetValue(r),phase=r.GetType().GetProperty("phase").GetValue(r),time=r.GetType().GetProperty("time").GetValue(r)}));}return Run();

