async Task<object> Case(string name,float first,float second,float flip,Vector2 destination,int variant=0){var w=await Load();var enemy=w.Bodies[0];var crate=w.Bodies[1];var eh=enemy.GetComponent<Health>();var ch=w.PlayerHealth;var damage=new List<object>();var marks=new List<object>();var spread=new List<object>();var traces=new List<object>();var inputs=new List<object>();w.DamageCommitted+=d=>damage.Add(new{step=d.Step,time=w.SimulationTime,source=d.SourceId,target=d.TargetId,kind=d.Kind.ToString(),hp=d.RemainingHealth,speed=d.NormalSpeed,pos=V(d.Position)});w.MarkResolved+=m=>marks.Add(new{step=w.CompletedStepCount,time=w.SimulationTime,id=m.Request.TargetId,polarity=m.Request.Polarity.ToString(),outcome=m.Outcome.ToString(),remaining=m.RemainingMarks});w.PropagationCommitted+=p=>spread.Add(p);Vector2 previous=new Vector2(99,99);float crateMoved=0;for(int j=0;j<1500&&w.State.Phase==LevelPhase.Running;j++){if(j==Mathf.RoundToInt(first/.02f))w.SubmitMark(enemy.BodyId,variant==1?Polarity.Model.Polarity.Negative:Polarity.Model.Polarity.Positive);if(j==Mathf.RoundToInt(second/.02f))w.SubmitMark(crate.BodyId,variant==1?Polarity.Model.Polarity.Positive:variant==2?Polarity.Model.Polarity.Positive:Polarity.Model.Polarity.Negative);if(j==Mathf.RoundToInt(flip/.02f)&&variant!=2)w.SubmitMark(variant==3?enemy.BodyId:crate.BodyId,variant==1||variant==3?Polarity.Model.Polarity.Negative:Polarity.Model.Polarity.Positive);Walk(w,j>=Mathf.RoundToInt(flip/.02f)?destination:new Vector2(3,2));var intent=w.Player.MoveIntent;if(intent!=previous){inputs.Add(new{step=j,move=V(intent)});previous=intent;}Step(w);crateMoved=Mathf.Max(crateMoved,Vector2.Distance(crate.Rigidbody.position,new Vector2(.5f,0)));if(j%10==0||w.State.Phase!=LevelPhase.Running)traces.Add(new{step=w.CompletedStepCount,time=w.SimulationTime,p=V(w.Player.Rigidbody.position),e=V(enemy.Rigidbody.position),c=V(crate.Rigidbody.position),hp=eh.CurrentHealth,ep=enemy.CurrentPolarity.ToString(),cp=crate.CurrentPolarity.ToString()});}return new{name,first,second,flip,variant,destination=V(destination),phase=w.State.Phase.ToString(),time=w.SimulationTime,steps=w.CompletedStepCount,attempts=w.SimulationAttemptCount,failed=w.FailedStepCount,hp=w.PlayerHealth.CurrentHealth,enemyHP=eh.CurrentHealth,remaining=w.State.RemainingMarks,crateMoved,damage,marks,spread,inputs,trace=traces,gmInvincible=w.GetComponent<GMManager>().Invincible,gmUnlimited=w.GetComponent<GMManager>().UnlimitedMarks};}
async Task<string> Run(){var runs=new List<object>();foreach(float flip in new[]{2f,2.5f,3f,3.5f,4f})runs.Add(await Case("separated clicks",.4f,.8f,flip,new Vector2(0,-3)));System.IO.File.WriteAllText("D:/Code/Polarity/docs/verification/步骤13-操作时序探索.json",JsonConvert.SerializeObject(runs));return JsonConvert.SerializeObject(runs.Select(r=>new{name=r.GetType().GetProperty("name").GetValue(r),flip=r.GetType().GetProperty("flip").GetValue(r),phase=r.GetType().GetProperty("phase").GetValue(r),time=r.GetType().GetProperty("time").GetValue(r),hp=r.GetType().GetProperty("hp").GetValue(r)}));}return Run();

